import { roundCents } from './money';
import { recordPayment } from './ledger';

/** Charges a card for an amount, in cents once rounded. */
export function chargeCard(amount: number): number {
  const cents = roundCents(amount);
  recordPayment(cents);
  return cents;
}

export function refundCard(amount: number): number {
  const cents = roundCents(amount);
  recordPayment(-cents);
  return -cents;
}

src/billing/money.ts:
export function roundCents(amount: number): number {
  return Math.round(amount * 100);
}

export function addTax(cents: number, rate: number): number {
  return roundCents((cents / 100) * (1 + rate));
}

export function splitCents(cents: number, parts: number): number {
  return Math.floor(cents / parts);
}

src/billing/ledger.ts:
const entries: number[] = [];

export function recordPayment(cents: number): number {
  entries.push(cents);
  return entries.length;
}

export function ledgerBalance(): number {
  return entries.reduce((sum, cents) => sum + cents, 0);
}

export function ledgerSize(): number {
  return entries.length;
}

