src/api/checkout.ts:
import { chargeCard } from '../billing/charge';
import { cartTotal, validateCart } from './cart';

/** Charges the cart's total. */
export function checkout(total: number): number {
  validateCart(total);
  return chargeCard(cartTotal(total));
}

src/api/cart.ts:
export function validateCart(total: number): number {
  if (total <= 0) throw new Error('empty cart');
  return total;
}

export function cartTotal(total: number): number {
  return total + shipping(total);
}

export function shipping(total: number): number {
  return total > 50 ? 0 : 5;
}

