import { userRows } from '../db/users';
import { formatAmount } from './format';

export function getUser(id: string): string {
  return userName(id);
}

export function userName(id: string): string {
  return `user ${id}`;
}

export function userCredit(id: string): string {
  return formatAmount(id.length * 100);
}

const ACTIVE_DAYS = 30;

/** The users the dashboard counts as active: seen in the last 30 days, the team's test accounts left out. */
export function countActiveUsers(now: number): number {
  const since = now - ACTIVE_DAYS * 24 * 60 * 60 * 1000;
  return userRows().filter((user) => !user.test && user.lastSeen >= since).length;
}

