src/jobs/retry.ts:
import { chargeCard } from '../billing/charge';
import { backoff } from './schedule';

/** Charges again what failed, waiting longer each time. */
export function retryFailedCharges(amounts: number[]): number {
  return amounts.reduce((sum, amount, attempt) => sum + chargeCard(amount) + backoff(attempt), 0);
}

src/jobs/schedule.ts:
export function backoff(attempt: number): number {
  return Math.min(2 ** attempt, maxDelay());
}

export function maxDelay(): number {
  return 60;
}

export function nextRun(now: number): number {
  return now + maxDelay() * 1000;
}

src/jobs/cleanup.ts:
import { nextRun } from './schedule';

export function cleanupSessions(now: number): number {
  return nextRun(now) - now;
}

export function cleanupCarts(now: number): number {
  return cleanupSessions(now) * 2;
}

export function purgeLogs(days: number): number {
  return days * 24;
}

src/jobs/report.ts:
import { purgeLogs } from './cleanup';

export function dailyReport(day: number): number {
  return purgeLogs(day) + weeklyTotals(day);
}

export function weeklyTotals(day: number): number {
  return day * 7;
}

src/billing/discount.ts:
import { roundCents } from './money';

export function applyDiscount(cents: number, code: string): number {
  return code === 'SAVE10' ? roundCents((cents / 100) * 0.9) : cents;
}

export function discountRate(code: string): number {
  return code === 'SAVE10' ? 0.1 : 0;
}

export function isValidCode(code: string): boolean {
  return discountRate(code) > 0;
}

src/api/orders.ts:
import { formatDate } from './format';

export function createOrder(total: number): number {
  return orderId(total);
}

export function orderId(total: number): number {
  return Math.floor(total * 31) % 997;
}

export function orderDate(at: Date): string {
  return formatDate(at);
}

export function listOrders(count: number): number[] {
  return Array.from({ length: count }, (_, i) => createOrder(i));
}

src/jobs/notify.ts:
import { dailyReport } from './report';

export function notifyOwner(day: number): string {
  return `report ${dailyReport(day)}`;
}

export function notifyFailures(count: number): string {
  return count > 0 ? `${count} failed` : notifyNone();
}

export function notifyNone(): string {
  return 'nothing failed';
}

