/** A user as the database stores it: lastSeen in milliseconds since the epoch, test for the team's own accounts. */
export interface UserRow {
  id: string;
  lastSeen: number;
  test: boolean;
}

const ROWS: UserRow[] = [
  { id: 'u1', lastSeen: 1_790_000_000_000, test: false },
  { id: 'u2', lastSeen: 1_780_000_000_000, test: false },
  { id: 'qa', lastSeen: 1_790_000_000_000, test: true },
];

export function userRows(): UserRow[] {
  return [...ROWS];
}
